style.css:
@-moz-document domain("youtube.com") {
/* ----- GLOBAL PASTEL RAINBOW BG ----- */
  body, ytd-app, #content, #page-manager {
    background: linear-gradient(
      135deg,
      #ffe7f3 0%,
      #ffeef9 15%,
      #fff7fd 30%,
      #f9f2ff 45%,
      #e8f4ff 60%,
      #eafffa 75%,
      #f9ffef 90%
    ) !important;
    color: #4b4b4b !important;
  }

  /* ----- SOFT SPARKLES (CSS-only noise) ----- */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 99999;
    background:
      radial-gradient(circle, rgba(255,255,255,0.9) 0%, transparent 70%) 10% 20% / 6px 6px,
      radial-gradient(circle, rgba(255,255,255,0.9) 0%, transparent 70%) 80% 60% / 5px 5px,
      radial-gradient(circle, rgba(255,255,255,0.9) 0%, transparent 70%) 50% 80% / 7px 7px,
      repeating-linear-gradient(
        45deg,
        rgba(255,255,255,0.15) 0px,
        rgba(255,255,255,0.15) 1px,
        transparent 1px,
        transparent 3px
      );
    opacity: 0.5;
    animation: sparkleFloat 8s ease-in-out infinite alternate;
  }

  @keyframes sparkleFloat {
    from { transform: translateY(0px); }
    to   { transform: translateY(-10px); }
  }

  /* ----- TOP BAR (soft pastel blue) ----- */
  ytd-masthead {
    background: #d7e8ff !important;
    border-bottom: none !important;
    backdrop-filter: blur(8px);
  }

  /* ----- SEARCH BAR ----- */
  #search-input input {
    background: white !important;
    border: 2px solid #ffcce9 !important;
    border-radius: 14px !important;
    color: #4b4b4b !important;
  }

  #search-icon-legacy {
    background: #ffd6f4 !important;
    border-radius: 14px !important;
  }

  /* ----- VIDEO CARDS (cloudy pastel boxes) ----- */
  ytd-rich-item-renderer,
  ytd-video-renderer {
    background: rgba(255,255,255,0.75) !important;
    border-radius: 20px !important;
    border: 2px solid rgba(255,200,230,0.4) !important;
    box-shadow:
      0 4px 12px rgba(255,180,220,0.25),
      0 0 8px rgba(255,200,240,0.15);
    backdrop-filter: blur(6px);
  }

  /* ----- TITLES ----- */
  #video-title {
    color: #5a5a5a !important;
    font-weight: 600 !important;
    text-shadow: 0 0 4px rgba(255,255,255,0.8);
  }

  /* ----- LINKS ----- */
  a, yt-formatted-string {
    color: #8a74ff !important;
  }

  /* ----- BUTTONS (cute pill-shape) ----- */
  ytd-subscribe-button-renderer button {
    background: linear-gradient(90deg, #ffc0e6, #d6c3ff) !important;
    color: white !important;
    border-radius: 30px !important;
    border: none !important;
    padding: 0 16px !important;
    font-weight: bold !important;
    box-shadow: 0 3px 10px rgba(200,160,255,0.4);
  }

  /* ----- COMMENTS ----- */
  #comments {
    background: rgba(255,255,255,0.7) !important;
    border-radius: 20px !important;
    border: 2px solid rgba(255,200,230,0.4) !important;
  }

  #content-text {
    color: #4b4b4b !important;
  }

  /* ----- SCROLLBAR ----- */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #ffd6f4, #d2e1ff) !important;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #fdf5ff !important;
  }
}
